def gen(rng):
    def build(r, c, q, step=99, start=None):
        if start is None:
            start = rng.randint(-10**7, -10**7 + 50)
        v = start - 1
        rows = []
        vals = []
        for i in range(r):
            row = []
            for j in range(c):
                v += rng.randint(1, step) if j == 0 else rng.randint(0, step)
                row.append(v)
                vals.append(v)
            rows.append(row)
        lo, hi = max(-10**7, vals[0] - 5), min(10**7, vals[-1] + 5)
        qs = []
        for _ in range(q):
            t = rng.random()
            if t < 0.45:
                qs.append(rng.choice(vals))
            elif t < 0.7:
                qs.append(max(-10**7, min(10**7, rng.choice(vals) + rng.choice([-1, 1]))))
            else:
                qs.append(rng.randint(lo, hi))
        return f'{r} {c}\n' + '\n'.join(' '.join(map(str, row)) for row in rows) + f'\n{q}\n' + '\n'.join(map(str, qs))
    tests = [build(1, 1, 3, 3), build(1, 5, 6, 3), build(5, 1, 6, 3), build(2, 2, 5, 2)]
    for _ in range(14):
        tests.append(build(rng.randint(1, 5), rng.randint(1, 5), rng.randint(1, 8), rng.choice([1, 3, 20])))
    tests.append(build(1, 100000, 100000))
    tests.append(build(100000, 1, 100000))
    tests.append(build(316, 316, 100000))
    tests.append(build(250, 400, 100000))
    tests.append(build(1, 1, 100000, 1))
    return tests
